#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y * blockDim.y * 2 + threadIdx.y;
    int col = blockIdx.x * blockDim.x * 2 + threadIdx.x;

    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    float sum1 = 0.0f;
    float sum2 = 0.0f;
    float sum3 = 0.0f;
    float sum4 = 0.0f;

    // Precompute global row/col indices
    int row1 = row;
    int row2 = row + BLOCK_SIZE;
    int col1 = col;
    int col2 = col + BLOCK_SIZE;

    // Loop over tiles
    for (int tile = 0; tile < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; tile++) {
        int tile_offset = tile * BLOCK_SIZE;

        // Load tile of A into shared memory
        int a_col = tile_offset + threadIdx.x;
        if (row1 < N && a_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row1 * N + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (row2 < N && a_col < N) {
            As[threadIdx.y + BLOCK_SIZE][threadIdx.x] = A[row2 * N + a_col];
        } else {
            As[threadIdx.y + BLOCK_SIZE][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row = tile_offset + threadIdx.y;
        if (b_row < N && col1 < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + col1];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (b_row < N && col2 < N) {
            Bs[threadIdx.y][threadIdx.x + BLOCK_SIZE] = B[b_row * N + col2];
        } else {
            Bs[threadIdx.y][threadIdx.x + BLOCK_SIZE] = 0.0f;
        }

        __syncthreads();

        // Compute partial products with loop unrolling
        for (int k = 0; k < BLOCK_SIZE; k += UNROLL_FACTOR) {
            float a_val1 = As[threadIdx.y][k];
            float a_val2 = As[threadIdx.y][k+1];
            float a_val3 = As[threadIdx.y][k+2];
            float a_val4 = As[threadIdx.y][k+3];

            sum1 += a_val1 * Bs[k][threadIdx.x];
            sum1 += a_val2 * Bs[k+1][threadIdx.x];
            sum1 += a_val3 * Bs[k+2][threadIdx.x];
            sum1 += a_val4 * Bs[k+3][threadIdx.x];

            sum2 += a_val1 * Bs[k][threadIdx.x + BLOCK_SIZE];
            sum2 += a_val2 * Bs[k+1][threadIdx.x + BLOCK_SIZE];
            sum2 += a_val3 * Bs[k+2][threadIdx.x + BLOCK_SIZE];
            sum2 += a_val4 * Bs[k+3][threadIdx.x + BLOCK_SIZE];

            float a_val5 = As[threadIdx.y + BLOCK_SIZE][k];
            float a_val6 = As[threadIdx.y + BLOCK_SIZE][k+1];
            float a_val7 = As[threadIdx.y + BLOCK_SIZE][k+2];
            float a_val8 = As[threadIdx.y + BLOCK_SIZE][k+3];

            sum3 += a_val5 * Bs[k][threadIdx.x];
            sum3 += a_val6 * Bs[k+1][threadIdx.x];
            sum3 += a_val7 * Bs[k+2][threadIdx.x];
            sum3 += a_val8 * Bs[k+3][threadIdx.x];

            sum4 += a_val5 * Bs[k][threadIdx.x + BLOCK_SIZE];
            sum4 += a_val6 * Bs[k+1][threadIdx.x + BLOCK_SIZE];
            sum4 += a_val7 * Bs[k+2][threadIdx.x + BLOCK_SIZE];
            sum4 += a_val8 * Bs[k+3][threadIdx.x + BLOCK_SIZE];
        }

        __syncthreads();
    }

    // Write results
